"""Configure the Android template generated by the pinned Flutter SDK."""
from pathlib import Path
p = Path('android/app/build.gradle.kts')
s = p.read_text().replace('minSdk = flutter.minSdkVersion', 'minSdk = 23').replace('com.nexchat.nexchat', 'com.nexchat.app')
# Keep Flutter's compatible AGP / Kotlin / Gradle versions together.
if Path('android/key.properties').exists():
    s = 'import java.util.Properties\nimport java.io.FileInputStream\n' + s
    s = s.replace('android {', '''val signingProperties = Properties().apply {
    load(FileInputStream(rootProject.file("key.properties")))
}
android {
    signingConfigs {
        create("release") {
            keyAlias = signingProperties.getProperty("keyAlias")
            keyPassword = signingProperties.getProperty("keyPassword")
            storeFile = rootProject.file(signingProperties.getProperty("storeFile"))
            storePassword = signingProperties.getProperty("storePassword")
        }
    }
''', 1).replace('signingConfigs.getByName("debug")', 'signingConfigs.getByName("release")')
p.write_text(s)
p = Path('android/app/src/main/AndroidManifest.xml')
p.write_text(p.read_text().replace('android:label="nexchat"', 'android:label="NexChat"').replace('<application', '<uses-permission android:name="android.permission.INTERNET"/>\n    <application', 1))

for activity in Path("android/app/src/main/kotlin").rglob("MainActivity.kt"):
    activity.write_text(activity.read_text().replace("com.nexchat.nexchat", "com.nexchat.app"))
